//! The `ErrorInfo` trait: the metadata of an error.

use crate::Location;

/// The metadata of an error, read the same way for every error type.
///
/// Every type generated by `define_errors!` implements it. A hand-written error
/// type can implement it with `impl ErrorInfo for MyError {}` and override what
/// it needs: every method has a default. The trait is object safe, so
/// `&dyn ErrorInfo` works.
///
/// `0.3.0` ships the methods that need no codes or categories; `0.4.0` adds
/// `code`, `code_info`, `category`, `severity`, `kinds`, `public_message`,
/// `help`, `action`, `is_retryable`, and `retry_after`, each with a default, so
/// existing implementations keep compiling.
///
/// # Examples
///
/// ```
/// use define_err::prelude::*;
///
/// define_errors! {
///     pub enum StoreError {
///         Full { #[location] at: Location } => "the store is full",
///     }
/// }
///
/// let err = StoreError::Full { at: define_err::here() };
/// assert_eq!(err.type_name(), "StoreError::Full");
/// assert_eq!(err.location().unwrap().line(), line!() - 2);
/// ```
pub trait ErrorInfo: core::error::Error {
    /// Where the error was built or converted, when the variant records it in a
    /// `#[location]` field.
    ///
    /// # Examples
    ///
    /// ```
    /// use define_err::ErrorInfo;
    ///
    /// #[derive(Debug)]
    /// struct Plain;
    /// impl core::fmt::Display for Plain {
    ///     fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result { f.write_str("plain") }
    /// }
    /// impl core::error::Error for Plain {}
    /// impl ErrorInfo for Plain {}
    ///
    /// assert!(Plain.location().is_none());
    /// ```
    #[inline]
    fn location(&self) -> Option<Location> {
        None
    }

    /// The name of the error type, `"Type::Variant"` for generated types
    /// (OpenTelemetry `exception.type`).
    ///
    /// The default is `core::any::type_name::<Self>()`, the full path of the
    /// implementing type.
    ///
    /// # Examples
    ///
    /// ```
    /// use define_err::prelude::*;
    ///
    /// define_errors! {
    ///     pub struct Cancelled => "operation cancelled";
    /// }
    ///
    /// assert_eq!(Cancelled.type_name(), "Cancelled");
    /// ```
    #[inline]
    fn type_name(&self) -> &'static str {
        core::any::type_name::<Self>()
    }
}

#[cfg(test)]
mod tests {
    use core::fmt;

    use super::ErrorInfo;

    #[derive(Debug)]
    struct Manual;

    impl fmt::Display for Manual {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            f.write_str("manual")
        }
    }

    impl core::error::Error for Manual {}

    impl ErrorInfo for Manual {}

    #[test]
    fn test_error_info_defaults_for_hand_written_type() {
        assert!(Manual.location().is_none());
        assert!(Manual.type_name().ends_with("Manual"));
    }

    #[test]
    fn test_error_info_object_safe_type_name_is_concrete() {
        let dynamic: &dyn ErrorInfo = &Manual;
        assert!(dynamic.type_name().ends_with("Manual"));
    }
}
